sys_variable_value.value:
(function execute(inputs, outputs) {

    var queue = inputs.queue_record;

    if (!queue || !queue.isValidRecord()) {
        outputs.success = false;
        outputs.message = 'Invalid queue record.';
        return;
    }

    if (queue.getValue('status') != 'missed') {
        outputs.success = false;
        outputs.message = 'Only Missed queue records can rejoin.';
        return;
    }

    queue.setValue('status', 'waiting');

    var rejoinCount = parseInt(queue.getValue('rejoin_count'), 10) || 0;
    queue.setValue('rejoin_count', rejoinCount + 1);

    queue.setValue('arrival_time', new GlideDateTime());

    queue.setValue('missed_time', '');
    queue.setValue('called_time', '');
    queue.setValue('response_window_until', '');
    queue.setValue('queue_position', '');

    queue.update();

    outputs.success = true;
    outputs.message = 'Student successfully rejoined the queue.';

})(inputs, outputs);

